/* SPDX-License-Identifier: Apache-2.0
 *
 * Zephyr ADC example with hardware oversampling.
 * Target board: nrf52840dk/nrf52840
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/util.h>

#define ADC_RESOLUTION      12
#define ADC_OVERSAMPLING    4   /* 2^4 = 16 samples */
#define ADC_CHANNEL_ID      0

/* Sample buffer – one 16‑bit sample is enough for 12‑bit resolution */
static int16_t sample_buffer[1];

void main(void)
{
    const struct device *adc_dev = DEVICE_DT_GET(DT_ALIAS(adc0));
    int ret;

    if (!device_is_ready(adc_dev)) {
        printk("ADC device not ready\n");
        return;
    }

    /* Channel configuration */
    struct adc_channel_cfg channel_cfg = {
        .gain = ADC_GAIN_1,
        .reference = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id = ADC_CHANNEL_ID,
    };

    ret = adc_channel_setup(adc_dev, &channel_cfg);
    if (ret) {
        printk("Failed to configure ADC channel (%d)\n", ret);
        return;
    }

    /* Sequence configuration */
    struct adc_sequence sequence = {
        .channels = BIT(ADC_CHANNEL_ID),
        .buffer = sample_buffer,
        .buffer_size = sizeof(sample_buffer),
        .resolution = ADC_RESOLUTION,
        .oversampling = ADC_OVERSAMPLING,
        .calibrate = false,
    };

    printk("Starting ADC read loop (oversampling = %d)\n", ADC_OVERSAMPLING);

    while (1) {
        ret = adc_read(adc_dev, &sequence);
        if (ret) {
            printk("ADC read error (%d)\n", ret);
        } else {
            int16_t raw = sample_buffer[0];
            printk("ADC raw sample: %d\n", raw);
        }

        k_sleep(K_SECONDS(1));
    }
}
